    /**
     * start of illegal activity flagging
     */

    let initializeFlags = function () {
        clearFlags();
        if (typeof $scope.itemGroupState.flagsDetailed == "string") $scope.itemGroupState.flagsDetailed = JSON.parse($scope.itemGroupState.flagsDetailed);

        $(function () {
            $(window).focus(onWindowFocus);
            $(window).blur(onWindowBlur);
            $("input:text, textarea").on("paste", onPaste);
            $("input:text, textarea").on("cut", onCopy);
            $("input:text, textarea").on("copy", onCopy);
            $(window).on("mousemove keydown", onUserInput);
        });
    };

    let clearFlags = function () {
        lastBlurTime = null;
        lastInputTime = null;
        beforeCopyText = {};

        $(function () {
            $(window).off("focus");
            $(window).off("blur");
            $("input:text, textarea").off("paste");
            $("input:text, textarea").off("cut");
            $("input:text, textarea").off("copy");
            $(window).off("mousemove keydown");
        });
    };

    let onWindowBlur = function () {
        lastBlurTime = new Date();
    };

    let onWindowFocus = function () {
        if (lastBlurTime !== null) {
            let diff = (new Date() - lastBlurTime) / 1000;
            if (diff > blurTolerance) {
                console.log("long blur detected");
                $scope.itemGroupState.flags = $scope.itemGroupState.flags | 1;
                let flagsDetailed = $scope.itemGroupState.flagsDetailed;
                if (!flagsDetailed.hasOwnProperty("f1")) {
                    flagsDetailed.f1 = {};
                }
                if (!flagsDetailed.f1.hasOwnProperty("timeBlurred")) {
                    flagsDetailed.f1.timeBlurred = [];
                }
                flagsDetailed.f1.timeBlurred = flagsDetailed.f1.timeBlurred.concat(diff);
            }
        }
    };

    let onCopy = function (ev) {
        let contentText = $(ev.target).val().replace(/\r/g, "");
        beforeCopyText[ev.target.name] = contentText;
    };

    let beforeCopyTextContains = function (name, text) {
        if (name in beforeCopyText) {
            return beforeCopyText[name].indexOf(text) !== -1;
        }
        return false;
    };

    let onPaste = function (ev) {
        let pastedText = "";
        if (ev.originalEvent.clipboardData) pastedText = ev.originalEvent.clipboardData.getData('text');
        else if (window.clipboardData) pastedText = window.clipboardData.getData('text');
        pastedText = pastedText.replace(/\r/g, "");
        if (!pastedText) return;
        let contentText = $(ev.target).val().replace(/\r/g, "");
        let name = ev.target.name;
        if (contentText.indexOf(pastedText) === -1 && !beforeCopyTextContains(name, pastedText)) {
            console.log("invalid paste content detected");
            $scope.itemGroupState.flags = $scope.itemGroupState.flags | 2;
            let flagsDetailed = $scope.itemGroupState.flagsDetailed;
            if (!flagsDetailed.hasOwnProperty("f2")) {
                flagsDetailed.f2 = {};
            }
            if (!flagsDetailed.f2.hasOwnProperty("textPasted")) {
                flagsDetailed.f2.textPasted = [];
            }
            flagsDetailed.f2.textPasted = flagsDetailed.f2.textPasted.concat(pastedText);
        }
    };

    let onUserInput = function () {
        if (lastInputTime !== null) {
            let diff = (new Date() - lastInputTime) / 1000;
            if (diff > noInputTolerance) {
                console.log("long idle period detected");
                $scope.itemGroupState.flags = $scope.itemGroupState.flags | 4;
                let flagsDetailed = $scope.itemGroupState.flagsDetailed;
                if (!flagsDetailed.hasOwnProperty("f4")) {
                    flagsDetailed.f4 = {};
                }
                if (!flagsDetailed.f4.hasOwnProperty("timeIdle")) {
                    flagsDetailed.f4.timeIdle = [];
                }
                flagsDetailed.f4.timeIdle = flagsDetailed.f4.timeIdle.concat(diff);
            }
        }
        lastInputTime = new Date();
    };

    /**
     * end of illegal activity flagging
     */

    let stopAllMedia = function () {
        $("video").each(function () {
            this.pause();
            if (document.fullscreenElement ||
                document.webkitFullscreenElement ||
                document.mozFullScreenElement) {

                if (document.exitFullscreen) document.exitFullscreen();
                else if (this.webkitExitFullscreen) this.webkitExitFullscreen();
                else if (this.mozCancelFullscreen) this.mozCancelFullscreen();
                else if (this.msExitFullscreen) this.msExitFullscreen();
            }
        });
    };

    /**
     * accessibility css handler
     */
    $scope.watchAccessibilityEvent = (name, event, fnCSS, fnAfterCSS) => {
        const isNotDefault = (eventName) => 
            (eventName === "changefontsize" && currentFontSize !== '1em') ||
            (eventName === "changecolours" && (bgColorCurrent !== defaultBGColor || fgColorCurrent !== defaultFGColor)) ||
            (eventName === "changehighlighter" && $scope.highlighter !== null)

        const onEvent = (ev) => {
            $(`#${name}`).remove();

            if (isNotDefault(ev.type)) {
                const css = fnCSS(ev);

                if (css && css.length) {
                    $("head").append(`<style id='${name}'>${css}</style>`);
                }
            }

            fnAfterCSS(ev);
        }

        const events = { "font":["changefontsize"], "colours":["changecolours"], "highlight":["changehighlighter","highlight"] }
        for (let eventName of events[event]) {
            document.addEventListener(eventName, onEvent, false);
            if (isNotDefault(eventName)) {
                onEvent(new CustomEvent(events[event]));
            }
        }

        return () => {
            for (let eventName of events[event]) document.removeEventListener(eventName, onEvent);
            $(`#${name}`).remove();
        }
    }
