    $scope.watchResizeEvent = (fn) => {
        let animationFrameId = null;

        function handleResize() {
            // If an animation frame is already scheduled, cancel it
            if (animationFrameId) {
                window.cancelAnimationFrame(animationFrameId);
            }

            // Schedule a new animation frame
            animationFrameId = window.requestAnimationFrame(function() {
                fn()
            });
        }

        window.addEventListener("resize", handleResize)

        return () => window.removeEventListener("resize", handleResize)
    }

    $scope.navigationRange = {
        index: 0,
        start: 0,
        end: testRunner.R.safeItemGroups.length,
        max: testRunner.R.safeItemGroups.length,
        total: testRunner.R.safeItemGroups.length,
        previous: false,
        next: false
    };

    $scope.resetNavigationRange = function(index, max) {
        if (max >= $scope.navigationRange.total) {
            $scope.navigationRange = {
                index,
                start: 0,
                end: $scope.navigationRange.total,
                max: $scope.navigationRange.total,
                total: $scope.navigationRange.total,
                previous: false,
                next: false
            };
            return;
        }

        const before = Math.round((max - 1) / 2);
        const after = max - before - 1;
        const newRange = {
            index,
            start: $scope.itemGroupIndex - before,
            end: $scope.itemGroupIndex + after + 1,
            max: max,
            total: testRunner.R.safeItemGroups.length,
            //previous: $scope.itemGroupIndex !== 0,
            //next: $scope.itemGroupIndex !== testRunner.R.safeItemGroups.length - 1
        };

        if (newRange.start < 0) {
            newRange.start = 0;
            newRange.end = newRange.max;
        }
        if (newRange.end > newRange.total) {
            newRange.start = newRange.total - newRange.max;
            newRange.end = newRange.total;
        }

        newRange.previous = newRange.start !== 0
        if (newRange.previous) newRange.start += 1

        newRange.next = newRange.end !== newRange.total
        if (newRange.next) newRange.end -= 1

        $scope.navigationRange = newRange;
    }

    $scope.checkNavigationRangeSize = () => {
        const navWidth = $("nav").get(0).getBoundingClientRect().width;
        const itemWidth = $("nav .nav-elem").get(0).getBoundingClientRect().width + 7; // elements have 5px margin
        const maxItems = Math.floor(navWidth / itemWidth);

        // only update scope if the navigation range has changed
        if (maxItems === $scope.navigationRange.max) return;

        $scope.resetNavigationRange($scope.navigationRange.index, maxItems);
    }
    $timeout($scope.checkNavigationRangeSize);
    document.addEventListener('changefontsize', $scope.checkNavigationRangeSize, false);

    $scope.moveNavigationRange = function(increment) {
        const {index, start, end, max, total, previous, next} = $scope.navigationRange;
        const newRange = {
            index,
            start: start + increment,
            end: end + increment,
            max,
            total,
            previous,
            next
        }

        if (previous) {
            if (newRange.start === 1) {
                newRange.start = 0;
                newRange.previous = false;
            }
        }
        else if (newRange.start > 0) {
            newRange.start += 1;
            newRange.previous = true;
        }

        if (next) {
            if (newRange.end === newRange.total - 1) {
                newRange.end = newRange.total;
                newRange.next = false;
            }
        }
        else if (newRange.end < newRange.total) {
            newRange.end -= 1;
            newRange.next = true;
        }

        $scope.navigationRange = newRange;
    }

