    function updateState() {
        if ($scope.itemGroup !== null) {
            $(".itemgroup-intro *").removeAttr("ng-html");
            let stimulusHighlight = $(".itemgroup-intro").html();
            let instructionsHighlight = $(".itemgroup-instructions").html();
            if (stimulusHighlight) {
                switch ($scope.itemGroupState.mode) {
                    case "elective":
                        $scope.itemGroupState.selectedElective.stimulusHighlight = stimulusHighlight;
                        $scope.itemGroupState.selectedElective.instructionsHighlight = instructionsHighlight;
                        break;
                    case "select_elective": case "simple":
                        $scope.itemGroupState.stimulusHighlight = stimulusHighlight;
                        $scope.itemGroupState.instructionsHighlight = instructionsHighlight;
                        break;
                }
            }
            for (let itemState of $scope.itemGroupState.items) {
                let question = $("#question" + itemState.id + "-highlight").html();
                if (!question) continue

                let item = $scope.items.find(item => item.id === itemState.id)
                if (!item) continue

                itemState.question = question;
                item.question = question;

                if (item.type !== 0) continue
                let highlightedOptions = [];
                $("#response_table label").each((i, el) => {
                    // append label innerHTML to options
                    const highlightedLabel = $(el).html();
                    if (highlightedLabel) highlightedOptions.push(highlightedLabel);
                    // convert highlightedOptions to a string representation of an array then update the item.options
                    item.options = JSON.stringify(highlightedOptions);
                })
            }
        }
    }

